import {
  boolean,
  int,
  mysqlEnum,
  mysqlTable,
  primaryKey,
  text,
  timestamp,
  varchar,
  unique
} from 'drizzle-orm/mysql-core';

// Establishments
export const establishment = mysqlTable('establishment', {
  id: int().primaryKey().autoincrement(),
  name: varchar({ length: 100 }).notNull(),
  address: varchar({ length: 255 }).notNull(),
  postalCode: varchar({ length: 10 }).notNull(),
  city: varchar({ length: 100 }).notNull(),
  rneCode: varchar({ length: 8 }).notNull().unique(),
});


// User
export const user = mysqlTable('user', {
  // UUID generated by Better Auth
  id: varchar({ length: 36 }).primaryKey(),

  // Personal information
  firstName: varchar({ length: 100 }).notNull(),
  lastName: varchar({ length: 100 }).notNull(),

  // Standard Better Auth field
  name: varchar({ length: 255 }).notNull(),

  // Username authentication
  username: varchar({ length: 100 }).notNull().unique(),

  // Email authentication
  email: varchar({ length: 255 }).notNull().unique(),

  role: mysqlEnum(['professor', 'visitor', 'admin'])
    .default('visitor')
    .notNull(),

  // Better Auth fields
  emailVerified: boolean().default(false).notNull(),
  image: text(),

  createdAt: timestamp().defaultNow().notNull(),
  updatedAt: timestamp().defaultNow().onUpdateNow().notNull(),

  // Better Auth username plugin
  displayUsername: varchar({ length: 100 }),

  // Better Auth admin plugin
  banned: boolean().default(false),
  banReason: text(),
  banExpires: timestamp(),
});


// Sessions - Better Auth
export const session = mysqlTable('session', {
  id: varchar({ length: 36 }).primaryKey(),
  expiresAt: timestamp().notNull(),
  token: varchar({ length: 255 }).notNull().unique(),
  createdAt: timestamp().defaultNow().notNull(),
  updatedAt: timestamp().defaultNow().onUpdateNow().notNull(),
  ipAddress: varchar({ length: 255 }),
  userAgent: text(),
  userId: varchar({ length: 36 })
    .notNull()
    .references(() => user.id, { onDelete: 'cascade' }),

  // Better Auth admin plugin
  impersonatedBy: varchar({ length: 36 }),
});

// Accounts - Better Auth
export const account = mysqlTable('account', {
  id: varchar({ length: 36 }).primaryKey(),
  accountId: varchar({ length: 255 }).notNull(),
  providerId: varchar({ length: 100 }).notNull(),
  userId: varchar({ length: 36 })
    .notNull()
    .references(() => user.id, { onDelete: 'cascade' }),
  accessToken: text(),
  refreshToken: text(),
  idToken: text(),
  accessTokenExpiresAt: timestamp(),
  refreshTokenExpiresAt: timestamp(),
  scope: text(),
  password: text(),
  createdAt: timestamp().defaultNow().notNull(),
  updatedAt: timestamp().defaultNow().onUpdateNow().notNull(),
});

// Verifications - Better Auth
export const verification = mysqlTable('verification', {
  id: varchar({ length: 36 }).primaryKey(),
  identifier: varchar({ length: 255 }).notNull(),
  value: text().notNull(),
  expiresAt: timestamp().notNull(),
  createdAt: timestamp().defaultNow().notNull(),
  updatedAt: timestamp().defaultNow().onUpdateNow().notNull(),
});

// User / Establishment
export const userEstablishment = mysqlTable(
  'userEstablishment',
  {
    userId: varchar({ length: 36 })
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),

    establishmentId: int()
      .notNull()
      .references(() => establishment.id, { onDelete: 'cascade' }),
  },
  (table) => [
    primaryKey({
      columns: [table.userId, table.establishmentId],
    }),
  ],
);

// Faculties & Departments
export const faculty = mysqlTable('faculty', {
  id: int().primaryKey().autoincrement(),
  name: varchar({ length: 100 }).notNull(),

  establishmentId: int()
    .notNull()
    .references(() => establishment.id, { onDelete: 'cascade' }),
});

export const department = mysqlTable('department', {
  id: int().primaryKey().autoincrement(),
  name: varchar({ length: 100 }).notNull(),

  facultyId: int()
    .notNull()
    .references(() => faculty.id, { onDelete: 'cascade' }),
});

// Courses, Modules, Chapters and Themes
export const theme = mysqlTable('theme', {
  id: int().primaryKey().autoincrement(),
  name: varchar({ length: 100 }).notNull(),

  departmentId: int()
    .notNull()
    .references(() => department.id, { onDelete: 'cascade' }),
});

export const chapter = mysqlTable('chapter', {
  id: int().primaryKey().autoincrement(),
  name: varchar({ length: 100 }).notNull(),

  themeId: int()
    .notNull()
    .references(() => theme.id, { onDelete: 'cascade' }),
});

export const courseModule = mysqlTable('courseModule', {
  id: int().primaryKey().autoincrement(),
  name: varchar({ length: 100 }).notNull(),

  chapterId: int()
    .notNull()
    .references(() => chapter.id, { onDelete: 'cascade' }),
});

export const course = mysqlTable('course', {
  id: int().primaryKey().autoincrement(),
  name: varchar({ length: 100 }).notNull(),

  moduleId: int()
    .notNull()
    .references(() => courseModule.id, { onDelete: 'cascade' }),
});

// A module can have multiple prerequisite modules
export const prerequisite = mysqlTable('prerequisite', {
    moduleId: int()
      .notNull()
      .references(() => courseModule.id, { onDelete: 'cascade' }),

    prerequisiteModuleId: int()
      .notNull()
      .references(() => courseModule.id, { onDelete: 'cascade' }),
  },
  (table) => [primaryKey({ columns: [table.moduleId, table.prerequisiteModuleId] })],
);

// Course elements
export const courseElement = mysqlTable('courseElement', {
  id: int().primaryKey().autoincrement(),
  title: varchar({ length: 100 }),
  type: mysqlEnum(['text', 'image']).notNull(),
  content: text(),
  description: text(),
  credit: varchar({ length: 100 }),
  license: varchar({ length: 100 }),
  courseId: int()
    .notNull()
    .references(() => course.id, { onDelete: 'cascade' }),

  // Kept when the author's account is deleted (authorId becomes null)
  authorId: varchar({ length: 36 })
    .references(() => user.id, { onDelete: 'set null' }),
  // Author's name copied at creation, so the trace remains after account deletion
  authorName: varchar({ length: 255 }).notNull(),

  createdAt: timestamp().defaultNow().notNull(),
});

// Favorites
export const favorite = mysqlTable(
  'favorite',
  {
    id: int().primaryKey().autoincrement(),
    userId: varchar({ length: 36 })
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),

    courseId: int().references(() => course.id, { onDelete: 'cascade' }),
    moduleId: int().references(() => courseModule.id, { onDelete: 'cascade' }),
    chapterId: int().references(() => chapter.id, { onDelete: 'cascade' }),
    themeId: int().references(() => theme.id, { onDelete: 'cascade' }),
    departmentId: int().references(() => department.id, { onDelete: 'cascade' }),

    createdAt: timestamp().defaultNow().notNull(),
  },
  (table) => [
    unique('uq_favorite_course').on(table.userId, table.courseId),
    unique('uq_favorite_module').on(table.userId, table.moduleId),
    unique('uq_favorite_chapter').on(table.userId, table.chapterId),
    unique('uq_favorite_theme').on(table.userId, table.themeId),
    unique('uq_favorite_department').on(table.userId, table.departmentId),
  ],
);

// Exercices
export const exercise = mysqlTable('exercise', {
  id: int().primaryKey().autoincrement(),
  title: varchar({ length: 100 }).notNull(),
});

// Question Group
export const questionGroup = mysqlTable(
  'questionGroup',
  {
    id: int().primaryKey().autoincrement(),

    exerciseId: int()
      .notNull()
      .references(() => exercise.id, { onDelete: 'cascade' }),

    position: int().notNull(),
  },
  (table) => [
    unique('uq_question_group_position').on(table.exerciseId, table.position),
  ],
);


// Questions
export const question = mysqlTable(
  'question',
  {
    id: int().primaryKey().autoincrement(),

    groupId: int()
      .notNull()
      .references(() => questionGroup.id, { onDelete: 'cascade' }),

    position: int().notNull(),

    moduleId: int()
      .notNull()
      .references(() => courseModule.id, { onDelete: 'cascade' }),

    statement: text().notNull(),
    media: varchar({ length: 255 }),
    points: int(),
    difficulty: int(),
  },
  (table) => [unique('uq_question_position').on(table.groupId, table.position),
  ],
);

// Answer options
export const answerOption = mysqlTable('answerOption', {
  id: int().primaryKey().autoincrement(),

  questionId: int()
    .notNull()
    .references(() => question.id, { onDelete: 'cascade' }),

  content: varchar({ length: 255 }).notNull(),
  isCorrect: boolean().notNull().default(false),
});